import React, { Suspense, useState, useEffect } from 'react';
import { HashRouter as Router, Routes, Route } from 'react-router-dom';

import ErrorPage from './components/common/Error';
import AuthPage from './pages/Form/AuthForm';
import PrivateRoute from './PrivateRoute';
import './App.css';
import Spinner from './components/common/Spinner';
import { ToastContainer } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

const Home = React.lazy(() => import('./pages/Home/Home'));
const Products = React.lazy(() => import('./pages/ProductList/Product'));
const ProductDetails = React.lazy(() => import('./pages/ProductDetails/Productdetails'));
const Checkout = React.lazy(() => import('./pages/Checkout/CheckOut'));
const ProductGrid = React.lazy(() => import('./pages/ProductGrid/Product'));
const Cart = React.lazy(() => import('./pages/Cart/Cart'));

const App = () => {
  const [isSignedIn, setIsSignedIn] = useState(false);
  const [userName, setUserName] = useState('');

  useEffect(() => {
    const isAuthenticated = localStorage.getItem('isAuthenticated');
    const user = JSON.parse(localStorage.getItem('user'));
    if (isAuthenticated && user) {
      setIsSignedIn(true);
      setUserName(user.name);
    }
  }, []);

  const handleSignIn = (name) => {
    setIsSignedIn(true);
    setUserName(name);
    localStorage.setItem('isAuthenticated', true);
  };

  return (
    <Router> {/* ✅ استخدام HashRouter بدلاً من BrowserRouter */}
      <Suspense fallback={<Spinner animation="border" variant="secondary" className='Loading' />}>
        <Routes>
          <Route path="/" element={<AuthPage onSignIn={handleSignIn} setUserName={setUserName} />} />
          <Route path="/home" element={<PrivateRoute><Home userName={userName} isSignedIn={isSignedIn} /></PrivateRoute>} />
          <Route path="/products" element={<Products />} />
          <Route path="/productgrid" element={<ProductGrid />} />
          <Route path="/products/:id" element={<ProductDetails />} />
          <Route path="/checkout" element={<Checkout userName={userName} isSignedIn={isSignedIn} />} />
          <Route path="/cart" element={<Cart />} />
          <Route path="*" element={<ErrorPage />} />
        </Routes>
      </Suspense>
      <ToastContainer />
    </Router>
  );
};

export default App;
